style.css:
@-moz-document domain("discord.com") {
/* ==========================================================
   OBSIDIAN NOIR: Obsidian Glass x Terminal Noir
   Frosted near-black glass panels + monospace type +
   phosphor-green accents + blinking-cursor message box.
   Built on CSS variables + partial-class selectors so it
   survives Discord's hashed class-name changes.
   ========================================================== */

/* ---------- 1. Palette (edit these to retune everything) ---------- */
:root,
.theme-dark,
.theme-darker,
.theme-midnight,
.theme-light {
  --on-bg-0: #040605;                          /* deepest layer */
  --on-bg-1: #090d0b;                          /* base */
  --on-glass: rgba(11, 17, 14, 0.62);          /* frosted panels */
  --on-glass-strong: rgba(8, 12, 10, 0.80);
  --on-border: rgba(57, 255, 136, 0.12);
  --on-border-hover: rgba(57, 255, 136, 0.34);
  --on-glow: rgba(57, 255, 136, 0.16);
  --on-text: #cfe9d8;
  --on-text-muted: #6f8d7b;
  --on-accent: #39ff88;                        /* phosphor green */
  --on-accent-dim: #1f9e57;
  --on-radius: 6px;
  --on-blur: blur(16px) saturate(130%);
  --on-font: "JetBrains Mono", "Fira Code", "Cascadia Code", "SF Mono",
             Consolas, "Courier New", monospace;
}

/* ---------- 2. Discord's own variables (new + legacy names) ---------- */
:root,
.theme-dark,
.theme-darker,
.theme-midnight,
.theme-light {
  /* current naming */
  --background-base-lowest: var(--on-bg-0) !important;
  --background-base-lower: var(--on-glass-strong) !important;
  --background-base-low: var(--on-glass) !important;
  --background-surface-high: rgba(14, 21, 17, 0.86) !important;
  --background-surface-higher: rgba(18, 27, 22, 0.90) !important;
  --background-surface-highest: rgba(22, 33, 27, 0.95) !important;
  --chat-background-default: transparent !important;
  --channels-default: var(--on-text-muted) !important;
  --text-default: var(--on-text) !important;
  --text-strong: #eafff2 !important;
  --text-muted: var(--on-text-muted) !important;
  --header-primary: #eafff2 !important;
  --header-secondary: var(--on-text-muted) !important;
  --interactive-normal: #86a894 !important;
  --interactive-hover: var(--on-accent) !important;
  --interactive-active: var(--on-accent) !important;
  --background-modifier-hover: rgba(57, 255, 136, 0.06) !important;
  --background-modifier-selected: rgba(57, 255, 136, 0.10) !important;
  --background-modifier-active: rgba(57, 255, 136, 0.14) !important;
  --channeltextarea-background: rgba(57, 255, 136, 0.04) !important;
  --scrollbar-thin-thumb: rgba(57, 255, 136, 0.28) !important;
  --scrollbar-thin-track: transparent !important;
  --scrollbar-auto-thumb: rgba(57, 255, 136, 0.28) !important;
  --scrollbar-auto-track: transparent !important;

  /* legacy naming (still used in places) */
  --background-primary: transparent !important;
  --background-secondary: var(--on-glass) !important;
  --background-secondary-alt: var(--on-glass-strong) !important;
  --background-tertiary: var(--on-bg-0) !important;
  --background-floating: rgba(8, 12, 10, 0.94) !important;
  --text-normal: var(--on-text) !important;
  --text-link: var(--on-accent) !important;

  /* fonts: Discord reads these variables for most text */
  --font-primary: var(--on-font) !important;
  --font-display: var(--on-font) !important;
  --font-headline: var(--on-font) !important;
  --font-code: var(--on-font) !important;
}

/* ---------- 3. Monospace everywhere ---------- */
body,
button,
input,
textarea,
select,
[class*="markup_"],
[class*="title_"],
[class*="name_"] {
  font-family: var(--on-font) !important;
}

[class*="markup_"] {
  letter-spacing: -0.01em;
}

/* ---------- 4. Backdrop: gives the glass something to blur ---------- */
html,
body {
  background: var(--on-bg-0) !important;
}

#app-mount {
  background:
    radial-gradient(900px 600px at 10% 6%, rgba(57, 255, 136, 0.07), transparent 60%),
    radial-gradient(800px 700px at 94% 92%, rgba(31, 158, 87, 0.08), transparent 60%),
    var(--on-bg-1) !important;
}

/* ---------- 5. Frosted panels with green hairlines ---------- */
[class*="sidebar_"],
[class*="guilds_"],
[class*="membersWrap_"],
[class*="sidebarList_"],
nav[class*="wrapper_"] {
  background: var(--on-glass) !important;
  -webkit-backdrop-filter: var(--on-blur);
  backdrop-filter: var(--on-blur);
  border-right: 1px solid var(--on-border) !important;
}

[class*="membersWrap_"] {
  border-right: 0 !important;
  border-left: 1px solid var(--on-border) !important;
}

/* top header bar */
[class*="chat_"] > [class*="subtitleContainer_"],
section[class*="title_"] {
  background: var(--on-glass-strong) !important;
  -webkit-backdrop-filter: var(--on-blur);
  backdrop-filter: var(--on-blur);
  border-bottom: 1px solid var(--on-border) !important;
  box-shadow: none !important;
}

/* user panel at bottom-left */
section[class*="panels_"],
div[class*="panels_"] {
  background: var(--on-glass-strong) !important;
  -webkit-backdrop-filter: var(--on-blur);
  backdrop-filter: var(--on-blur);
  border-top: 1px solid var(--on-border) !important;
}

/* ---------- 6. Green glow on hover ---------- */
[class*="containerDefault_"]:hover,
[class*="interactive_"]:hover,
[class*="channel_"]:hover {
  background: rgba(57, 255, 136, 0.06) !important;
  box-shadow: 0 0 0 1px var(--on-border-hover), 0 0 16px var(--on-glow);
  border-radius: var(--on-radius);
  transition: box-shadow 0.18s ease, background 0.18s ease;
}

/* selected channel / DM */
[class*="modeSelected_"] {
  background: rgba(57, 255, 136, 0.10) !important;
  box-shadow: inset 2px 0 0 var(--on-accent), inset 0 0 0 1px var(--on-border-hover);
  border-radius: var(--on-radius);
}

/* ---------- 7. Messages ---------- */
[class*="messageListItem_"] [class*="message_"]:hover,
li[class*="messageListItem_"]:hover > div {
  background: rgba(57, 255, 136, 0.035) !important;
}

[class*="mentioned_"] {
  background: rgba(57, 255, 136, 0.08) !important;
  box-shadow: inset 2px 0 0 var(--on-accent);
}

[class*="markup_"] a {
  color: var(--on-accent) !important;
  text-decoration: none;
  border-bottom: 1px dotted var(--on-accent-dim);
}

/* inline code and code blocks in terminal style */
[class*="markup_"] code {
  background: rgba(0, 0, 0, 0.45) !important;
  border: 1px solid var(--on-border) !important;
  color: var(--on-accent) !important;
  border-radius: 4px;
}

/* ---------- 8. Message box with blinking cursor ---------- */
[class*="channelTextArea_"] {
  background: var(--on-glass-strong) !important;
  -webkit-backdrop-filter: var(--on-blur);
  backdrop-filter: var(--on-blur);
  border: 1px solid var(--on-border) !important;
  border-bottom: 2px solid var(--on-accent-dim) !important;
  border-radius: var(--on-radius) !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  animation: on-cursor-blink 1.1s steps(1, end) infinite;
}

[class*="channelTextArea_"]:focus-within {
  border-color: var(--on-border-hover) !important;
  box-shadow: 0 0 22px var(--on-glow);
}

@keyframes on-cursor-blink {
  0%, 55%   { border-bottom-color: var(--on-accent); }
  56%, 100% { border-bottom-color: transparent; }
}

/* caret itself: green, block-shaped where the browser supports it */
[class*="textArea_"],
[class*="slateTextArea_"],
[contenteditable="true"] {
  caret-color: var(--on-accent);
  caret-shape: block;
}

/* ---------- 9. Popouts, menus, modals ---------- */
[class*="menu_"],
[class*="popout_"],
[class*="layer_"] [class*="container_"][role="dialog"],
[class*="modal_"],
[class*="tooltip_"] {
  border: 1px solid var(--on-border) !important;
  border-radius: var(--on-radius) !important;
  -webkit-backdrop-filter: var(--on-blur);
  backdrop-filter: var(--on-blur);
}

[class*="backdrop_"] {
  background: rgba(0, 0, 0, 0.65) !important;
}

/* ---------- 10. Inputs and search ---------- */
input[type="text"],
input[type="search"],
[class*="searchBar_"] {
  background: rgba(57, 255, 136, 0.04) !important;
  border: 1px solid var(--on-border) !important;
  border-radius: var(--on-radius) !important;
  caret-color: var(--on-accent);
}

/* ---------- 11. Scrollbars ---------- */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: transparent !important;
  border: 0 !important;
}
::-webkit-scrollbar-thumb {
  background: rgba(57, 255, 136, 0.28) !important;
  border-radius: 2px;
  border: 0 !important;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(57, 255, 136, 0.5) !important;
}

/* ---------- 12. Selection ---------- */
::selection {
  background: rgba(57, 255, 136, 0.30);
  color: #04120a;
}

/* ---------- 13. Respect reduced-motion settings ---------- */
@media (prefers-reduced-motion: reduce) {
  [class*="channelTextArea_"] {
    animation: none;
    border-bottom-color: var(--on-accent-dim) !important;
  }
}
}
